"""Tests for `gate.py coverage` -- replaces the "Coverage Pre-Check" at
src/agents/architect.md:28-41. Design spec:
docs/audits/2026-09-04-determinism-audit.md, sections 3.1, 5.

Schema for the deep-read payload's `chapter_coverage` field:
src/agents/deep-reader.md:112-146 (Step 1c). Per architect.md:32, an entry
without `status: "covered"` or `status: "skipped-irrelevant"` (with a
`reason`) is invalid; per architect.md:33, chapter numbers must form a
contiguous range with no gaps; per architect.md:34, every `evidence_ids`
entry must resolve against the deep-reader's evidence map.

Per TST-08, every check below has a companion test proving the gate can
fail, alongside a baseline fixture proving it passes clean.
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")
VALID_DEEP_READ_PATH = os.path.join(ROOT_DIR, "tests", "fixtures", "gate", "deep-read-valid.json")


def run_gate(*args):
    """Invoke gate.py as a real subprocess. Auto-injects a scratch
    --ledger into a throwaway tempdir when the caller didn't supply one --
    without this, gate.py resolves the ledger via $CLAUDE_PROJECT_DIR (or
    cwd) and would write into any REAL .academic-helper/session-state.json
    that happens to exist there (TST-09 spirit: no ambient-environment
    dependency, including this one).
    """
    if "--ledger" not in args and args:
        with tempfile.TemporaryDirectory() as ledger_dir:
            return subprocess.run(
                [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
                capture_output=True,
                text=True,
                timeout=30,
            )
    return subprocess.run(
        [sys.executable, GATE, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


def load_valid_deep_read():
    with open(VALID_DEEP_READ_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def run_on_deep_read(deep_read):
    with tempfile.TemporaryDirectory() as tmpdir:
        path = os.path.join(tmpdir, "deep-read.json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(deep_read, fh, ensure_ascii=False)
        return run_gate("coverage", path, "--json")


class TestValidFixturePasses(unittest.TestCase):
    def test_valid_fixture_passes(self):
        proc = run_gate("coverage", VALID_DEEP_READ_PATH, "--json")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")
        self.assertEqual(payload["violations"], [])

    def test_chapter_coverage_absent_is_a_no_op_pass(self):
        """Matches architect.md:41 -- absent chapter_coverage means the
        check did not apply, not that it failed.
        """
        proc = run_on_deep_read({"evidence": []})
        self.assertEqual(proc.returncode, 0, proc.stdout)


class TestChapterGap(unittest.TestCase):
    def test_skipping_a_chapter_fails(self):
        """Plant the exact mutation from the acceptance spec: a
        chapter_coverage array that skips chapter 3.
        """
        deep_read = load_valid_deep_read()
        entries = deep_read["chapter_coverage"]["Ezra"]
        deep_read["chapter_coverage"]["Ezra"] = [e for e in entries if e["chapter"] != 3]
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("chapter-gap", checks)
        gap_violation = [v for v in payload["violations"] if v["check"] == "chapter-gap"][0]
        self.assertIn("3", gap_violation["detail"])

    def test_contiguous_chapters_pass(self):
        deep_read = {
            "chapter_coverage": {
                "Book": [
                    {"chapter": 1, "status": "covered"},
                    {"chapter": 2, "status": "covered"},
                    {"chapter": 3, "status": "covered"},
                ]
            },
            "evidence": [],
        }
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 0, proc.stdout)


class TestDanglingEvidenceId(unittest.TestCase):
    def test_evidence_id_with_no_match_fails(self):
        deep_read = load_valid_deep_read()
        deep_read["chapter_coverage"]["Ezra"][0]["evidence_ids"].append("ev_does_not_exist")
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("dangling-evidence-id", checks)
        violation = [v for v in payload["violations"] if v["check"] == "dangling-evidence-id"][0]
        self.assertIn("ev_does_not_exist", violation["detail"])

    def test_evidence_map_as_dict_also_resolves(self):
        """deep-reader.md does not pin one shape for the evidence
        collection -- a dict keyed by id must resolve too.
        """
        deep_read = {
            "chapter_coverage": {
                "Book": [{"chapter": 1, "status": "covered", "evidence_ids": ["ev1"]}]
            },
            "evidence": {"ev1": {"note": "..."}},
        }
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 0, proc.stdout)


class TestInvalidStatus(unittest.TestCase):
    def test_unknown_status_value_fails(self):
        deep_read = {
            "chapter_coverage": {"Book": [{"chapter": 1, "status": "maybe-covered"}]},
            "evidence": [],
        }
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("invalid-status", checks)

    def test_missing_status_fails(self):
        deep_read = {"chapter_coverage": {"Book": [{"chapter": 1}]}, "evidence": []}
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 1, proc.stdout)

    def test_skipped_irrelevant_without_reason_fails(self):
        deep_read = {
            "chapter_coverage": {"Book": [{"chapter": 1, "status": "skipped-irrelevant"}]},
            "evidence": [],
        }
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("invalid-status", checks)

    def test_skipped_irrelevant_with_reason_passes(self):
        deep_read = {
            "chapter_coverage": {
                "Book": [{"chapter": 1, "status": "skipped-irrelevant", "reason": "not relevant"}]
            },
            "evidence": [],
        }
        proc = run_on_deep_read(deep_read)
        self.assertEqual(proc.returncode, 0, proc.stdout)


class TestMalformedInput(unittest.TestCase):
    def test_non_object_deep_read_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "deep-read.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump("just a string", fh)
            proc = run_gate("coverage", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)

    def test_unparseable_json_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "deep-read.json")
            with open(path, "w", encoding="utf-8") as fh:
                fh.write("{{{ not json")
            proc = run_gate("coverage", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)

    def test_chapter_coverage_wrong_shape_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "deep-read.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump({"chapter_coverage": "not an object"}, fh)
            proc = run_gate("coverage", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)


